  public boolean onTouchEvent(MotionEvent e){float x=e.getX(),y=e.getY();if(e.getAction()==MotionEvent.ACTION_DOWN){lastY=y;moving=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){if(screen==1){float dy=lastY-y;if(Math.abs(dy)>2)moving=true;scroll=Math.max(0,Math.min(d(900),scroll+dy));lastY=y;invalidate();}return true;}if(e.getAction()!=MotionEvent.ACTION_UP)return true;if(moving)return true;for(Hit h:new ArrayList<>(hits))if(h.r.contains(x,y)){handle(h.id);return true;}return true;}
  void handle(int id){if(id==1000){screen=1;}else if(id>=1100&&id<1110){screen=1;}else if(id>=2000&&id<2100){game=id-2000;screen=10;msg="READY";}else if(id==3000){st.claimDaily();}else if(id>=3010&&id<3014){int m=id-3010;if(st.mission(m)&&!st.claimed(m))st.claimMission(m);}else if(id>=4000&&id<4003){int s=id-4000;if(s==0)st.music=!st.music;if(s==1)st.sfx=!st.sfx;if(s==2)st.vibration=!st.vibration;st.save();}else if(id>=5000&&id<5005){screen=id-5000;scroll=0;}else if(id==6000){screen=1;game=-1;}else if(id==6100){bet=Math.max(100,bet/2);}else if(id==6101){bet=Math.min(100000,bet*2);}else if(id==6200){play();}invalidate();}
